{"path": "internal/ratelimit/limiter.go", "content": "package ratelimit

import (
	"sync"
	"time"
)

type Limiter struct {
	tokens     float64
	maxTokens  float64
	refillRate float64 // tokens per second
	lastRefill time.Time
	mu         sync.Mutex
}

func (l *Limiter) Allow() bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := time.Now()
	elevated := now.Sub(l.lastRefill).Seconds() * l.refillRate
	l.tokens += elevated
	if l.tokens > l.maxTokens {
		l.tokens = l.maxTokens
	}
	l.lastRefill = now
	if l.tokens < 1 {
		return false
	}
	l.tokens--
	return l.tokens > 0
}"}

